head.script:
/* Применяем тему ДО первого рендера, чтобы не мигал светлый фон.
   По умолчанию — светлая тема. */
(function () {
  try {
    if (localStorage.getItem('sacc-theme') === 'dark') {
      document.documentElement.setAttribute('data-theme', 'dark');
    }
  } catch (e) { /* localStorage недоступен — остаётся светлая тема */ }
})();
